    for(let index=0;index<105;index++){const value=byURL.get(siteOrigin+'/'+group+paths[index]).value;assert.equal(value.internal,true);assert.equal(value.final_status,200);assert.equal(value.error,null);assert.deepEqual(value.titles,index===1?[]:[titleFor(index===104?103:index)]);}
