async function genuineQuota(){return page.evaluate(nonce=>{const prefix='owned-quota-'+nonce+':';let chunk=262144,total=0,sequence=0,last=null,errorName=null,errorCode=null;const maximum=16*1024*1024;
  while(chunk>=1){try{if(total+chunk>maximum)throw Error('Owned browser quota fixture did not reach native quota within its bound');const key=prefix+sequence;localStorage.setItem(key,'q'.repeat(chunk));last=key;sequence++;total+=chunk;}catch(error){if(error.name!=='QuotaExceededError')throw error;errorName=error.name;errorCode=error.code;chunk=Math.floor(chunk/2);}}
  if(!last)throw Error('Owned quota fixture stored no data');let exhausted=false;for(let index=0;index<1024;index++){try{localStorage.setItem(last,localStorage.getItem(last)+'q');total++;}catch(error){if(error.name!=='QuotaExceededError')throw error;exhausted=true;break;}}if(!exhausted)throw Error('Owned quota fixture did not fill final available characters');return{prefix,keys:sequence,stored_code_units:total,error_name:errorName,error_code:errorCode,source:'actual_Chromium_localStorage_quota_no_monkeypatch'};
},nonce);}

